CREATE COLUMN TABLE "TEST_AP"."OUDO" ("Code" NVARCHAR(20) NOT NULL , "Name" NVARCHAR(100), "TableName" NVARCHAR(19) NOT NULL , "LogTable" NVARCHAR(20), "TYPE" NVARCHAR(1) DEFAULT '1', "MngSeries" NVARCHAR(1) DEFAULT 'N', "CanDelete" NVARCHAR(1) DEFAULT 'Y', "CanClose" NVARCHAR(1) DEFAULT 'N', "CanCancel" NVARCHAR(1) DEFAULT 'N', "ExtName" NVARCHAR(254), "CanFind" NVARCHAR(1) DEFAULT 'N', "CanYrTrnsf" NVARCHAR(1) DEFAULT 'N', "CanDefForm" NVARCHAR(1) DEFAULT 'N', "CanLog" NVARCHAR(1) DEFAULT 'N', "OvrWrtDll" NVARCHAR(1) DEFAULT 'Y', "UIDFormat" NVARCHAR(1) DEFAULT 'Y', "CanArchive" NVARCHAR(1) DEFAULT 'N', "MenuItem" NVARCHAR(1) DEFAULT 'N', "MenuCapt" NVARCHAR(254), "FatherMenu" INTEGER CS_INT, "Position" SMALLINT CS_INT, "CanNewForm" NVARCHAR(1) DEFAULT 'Y', "IsRebuild" NVARCHAR(1) DEFAULT 'Y', "NewFormSrf" NCLOB MEMORY THRESHOLD 1000, "MenuUid" NVARCHAR(32), "LstUpdDate" LONGDATE CS_LONGDATE, "LstUpdTime" INTEGER CS_INT, "CanApprove" NVARCHAR(1) DEFAULT 'N', "TemplateID" INTEGER CS_INT, PRIMARY KEY ("Code")) UNLOAD PRIORITY 5  AUTO MERGE ;
